package com.gymmind.knowledge.infrastructure.search; import java.util.List; public interface VectorIndexPort { void upsert(IndexedChunk chunk); List<IndexedChunk> search(float[] vector,Long tenantId); default List<IndexedChunk> search(float[] vector,Long tenantId,Long userId){return search(vector,tenantId).stream().filter(c->c.visibleTo(userId)).toList();} void delete(String id,Long tenantId); }
